import requests

from taf.hw.rf_attenuator.devices.jfw.jfw import JFW

from taf.rfrl.procedures.resources.python.rf_attenuator.exceptions import RebootNotExecuted, \
    ProgrammableAttenuatorError, AttenuatorRebootFailed


class Attenuator:
    """
    Arguments:
        info - object from testline configuration file concerning attenuator
        config - dictionary with configuration of attenuator ports

    Example of how config param should look like:
    config = {
        "MRBTS-50109/NRBTS-50109/NRCELL-1": {
            "Subcell-0": [
                {"antenna": "RMOD-1/ANTL-1", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-1/ANTL-2", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-1/ANTL-5", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-1/ANTL-6", "port": 0, "OFF": 0, "ON": 0},
            ],
            "Subcell-1": [
                {"antenna": "RMOD-2/ANTL-1", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-2/ANTL-2", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-2/ANTL-5", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-2/ANTL-6", "port": 0, "OFF": 0, "ON": 0},
            ],
            "Subcell-2": [
                {"antenna": "RMOD-3/ANTL-1", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-3/ANTL-2", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-3/ANTL-5", "port": 0, "OFF": 0, "ON": 0},
                {"antenna": "RMOD-3/ANTL-6", "port": 0, "OFF": 0, "ON": 0},
            ],
        }
    }
    """
    def __init__(self, info, config):
        self._ip = info.ip_addr
        self._port = info.port
        self.port_range = list(info.attenuation_port_numbers)
        self.config = config
        self._minimum_attenuation = 0
        self._maximum_attenuation = 127
        self._attenuator = JFW(ip=self._ip,
                               port=self._port,
                               min_attenuation=self._minimum_attenuation,
                               max_attenuation=self._maximum_attenuation)
        try:
            self._attenuator.connect()
        except EOFError:
            self.reboot_attenuator()
        finally:
            self._attenuator.connect()

    def __del__(self):
        self._attenuator.disconnect()

    def set_attenuation_on_port(self, port, value_db):
        """
        Sets the attenuation given by value_db on the selected port.
        :param port: attenuator port number
        :type port: int/str
        :param value_db: attenuation value in db
        :type value_db: float
        :return True of attenuation value where set correctly
                on programmable attenuator
        :rtype boolean
        :raises: ProgrammableAttenuatorError when attenuation
                 value wasn't correctly set on device.
        """
        self._attenuator.set_port_attenuation(port=str(port), attenuation_value=str(value_db) + 'db')
        actual_value_db = self._attenuator.read_port_attenuation(str(port))
        if int(actual_value_db) == int(value_db):
            return True
        else:
            raise ProgrammableAttenuatorError("Could not set desired attenuation value, "
                                              "please check your device!")

    def get_attenuation_on_port(self, port):
        """
        Reads attenuation value for selected port.
        :param port: attenuator port number
        :type port: int/str
        :return  attenuation value read from programmable attenuator
        :rtype int
        """
        return int(self._attenuator.read_port_attenuation(str(port)))

    def reboot_attenuator(self, timeout=60):
        """
        Reboots programmable attenuator via dedicated HTTP webpage
        by performing GET request on reboot resource.

        :param timeout: Timeout for device reboot time (in seconds, default to 60).
        :type timeout: str/int
        :raises RebootNotExecuted exception if GET request on reboot
                resource returned wrong status code (failed to run).
        :raises AttenuatorRebootFailed exception if webpage won't be accessible in given
                time via `timeout` parameter after reboot procedure
        """
        reboot = requests.get('http://{0}/cgi-bin/reboot.cgi'.format(self._attenuator.ip))
        if reboot.status_code == 200:
            self._is_attenuator_webpage_alive(timeout=timeout)

        else:
            raise RebootNotExecuted("Could not execute attenuator's reboot via HTTP "
                                    "(Status code: {} has been raised!)".format(reboot.status_code))

    def _is_attenuator_webpage_alive(self, timeout):
        retries = int(timeout) // 5

        for retry in range(retries):
            wake_up = requests.get('http://{0}'.format(self._attenuator.ip))
            if wake_up.status_code == 200:
                return

        raise AttenuatorRebootFailed("Couldn't bring attenuator to life "
                                     "after HTTP recovery reboot - please check your device.")
